import{_ as a,c as e,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"序卦傳","description":"周易正义 - 序卦傳","frontmatter":{"title":"序卦傳","description":"周易正义 - 序卦傳"},"headers":[],"relativePath":"zh/classics/zhengyi/068.md","filePath":"zh/classics/zhengyi/068.md"}'),t={name:"zh/classics/zhengyi/068.md"};function h(n,p,s,l,c,o){return r(),e("div",null,[...p[0]||(p[0]=[i('<p>开启夜间模式</p><p>菜单返回顶部 Sidebar Navigation 周易正义〔唐〕孔颖达1、【乾】 乾下乾上</p><p>2、【坤】 坤下坤上</p><p>3、【屯】 震下坎上</p><p>4、【蒙】 坎下艮上</p><p>5、【需】 乾下坎上</p><p>6、【讼】 坎下乾上</p><p>7、【师】 坎下坤上</p><p>8、【比】 坤下坎上</p><p>9、【小畜】 乾下巽上</p><p>10、【履】 兑下乾上</p><p>11、【泰】 乾下坤上</p><p>12、【否】 坤下乾上</p><p>13、【同人】 离下乾上</p><p>14、【大有】 乾下离上</p><p>15、【谦】 艮下坤上</p><p>16、【豫】 坤下震上</p><p>17、【随】 震下兑上</p><p>18、【蛊】 巽下艮上</p><p>19、【临】 兑下坤上</p><p>20、【观】 坤下巽上</p><p>21、【噬嗑】 震下离上</p><p>22、【贲】 离下艮上</p><p>23、【剥】 坤下艮上</p><p>24、【复】 震下坤上</p><p>25、【无妄】 震下乾上</p><p>26、【大畜】 乾下艮上</p><p>27、【颐】 震下艮上</p><p>28、【大过】 巽下兑上</p><p>29、【坎】 坎下坎上</p><p>30、【离】 离下离上</p><p>31、【咸】 艮下兑上</p><p>32、【恒】 巽下震上</p><p>33、【遁】 艮下乾上</p><p>34、【大壮】 乾下震上</p><p>35、【晋】 坤下离上</p><p>36、【明夷】 离下坤上</p><p>37、【家人】 离下巽上</p><p>38、【睽】 兑下离上</p><p>39、【蹇】 艮下坎上</p><p>40、【解】 坎下震上</p><p>41、【损】 兑下艮上</p><p>42、【益】 震下巽上</p><p>43、【夬】 乾下兑上</p><p>44、【姤】 巽下乾上</p><p>45、【萃】 坤下兑上</p><p>46、【升】 巽下坤上</p><p>47、【困】 坎下兑上</p><p>48、【井】 巽下坎上</p><p>49、【革】 离下兑上</p><p>50、【鼎】 巽下离上</p><p>51、【震】 震下震上</p><p>52、【艮】 艮下艮上</p><p>53、【渐】 艮下巽上</p><p>54、【归妹】 兑下震上</p><p>55、【丰】 离下震上</p><p>56、【旅】 艮下离上</p><p>57、【巽】 巽下巽上</p><p>58、【兑】 兑下兑上</p><p>59、【涣】 坎下巽上</p><p>60、【节】 兑下坎上</p><p>61、【中孚】 兑下巽上</p><p>62、【小过】 艮下震上</p><p>63、【既济】 离下坎上</p><p>64、【未济】 坎下离上</p><p>系辞传*上</p><p>系辞传*下</p><p>说卦传</p><p>序卦传</p><p>杂卦传</p><h1 id="序卦傳" tabindex="-1">序卦傳 <a class="header-anchor" href="#序卦傳" aria-label="Permalink to “序卦傳”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：《序卦》者，文王既繇六十四卦，分为上下二篇。其先后之次，其理不见，故孔子就上下二《经》，各序其相次之义，故谓之《序卦》焉。其周氏就《序卦》以六门往摄，第一天道门，第二人事门，第三相因门，第四相反门，第五相须门，第六相病门。如《乾》之次《坤》、《泰》之次《否》等，是天道运数门也。如《讼》必有《师》，《师》必有《比》等，是人事门也。如因《小畜》生《履》，因《履》故通等，是相因门也。如《遁》极反《壮》，动竟归止等，是相反门也。如《大有》须《谦》，《蒙》稚待养等，是相须也。如《贲》尽致《剥》，进极致伤等，是相病门也。韩康伯云：“《序卦》之所明，非《易》之缊也。盖因卦之次，讬象以明义。”不取深缊之义，故云“非《易》之缊”，故以取其人理也。今验六十四卦，二二相耦，非覆即变。覆者，表里视之，遂成两卦，《屯》、《蒙》、《需》、《讼》、《师》、《比》之类是也。变者，反覆唯成一卦，则变以对之，《乾》、《坤》、《坎》、《离》、《大过》、《颐》《中孚》、《小过》之类是也。且圣人本定先后，若元用孔子《序卦》之意，则不应非覆即变，然则康伯所云“因卦之次，讬象以明义”，盖不虚矣。故不用周氏之义。</p><p>有天地，然后万物生焉。盈天地之间者唯万物，故受之以《屯》，屯者，盈也。屯者，物之始生也。屯刚柔始交，故为物之始生也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：王肃云：“屯刚柔始交而难生，故为物始生也。”卢氏云：“物之始生故屯难。”皆以物之始生释屯难之义。案上言“屯者，盈也。”释《屯》次《乾》、《坤》，其言巳毕。更言“屯者，物之始生”者，开说下“物，生必蒙”，直取始生之意，非重释《屯》之名也。故韩康伯直引刚柔始交，以释物之始生也。</p><p>物生必蒙，故受之以《蒙》。蒙者，蒙也。物之稚也。物稚不可不养也，故受之以《需》。需者，饮食之道也。饮食必有讼，故受之以《讼》。夫有生则有资，有资则争兴也。讼必有众起，故受之以《师》。师者，众也。众必有所比，故受之以《比》。众起而不比，则争无由息；必相亲比，而后得宁也。比者，比也。比必有所畜，故受之以《小畜》。此非大通之道，则各有所畜以相济也。由比而畜，故曰“小畜”而不能大也。物畜然后有礼，故受之以《履》。履者，礼也。礼所以適用也。故既畜则宜用，有用则须礼也。履而泰然后安，故受之以《泰》，泰者，通也。物不可以终通，故受之以《否》。物不可以终否，故受之以《同人》。否则思通，人人同志，故可出门同人，不谋而合。与人同者，物必归焉，故受之以《大有》。有大者，不可以盈，故受之以《谦》。有大而能谦必豫，故受之以《豫》。豫必有随，顺以动者，众之所随。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：郑玄云：“喜乐而出，人则随从。孟子曰：吾君不游，吾何以休？吾君不豫，吾何以助？此之谓也。”王肃云：“欢豫，人必有随。”随者，皆以为人君喜乐欢豫，则以为人所随。案《豫卦·彖》云：“《豫》刚应而志行，顺以动《豫》。《豫》顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒。圣人以顺动，则刑罚清而民服。”即此上云“有大而能谦必豫，故受之以《豫》”，其意以圣人顺动能谦，为物所说，所以为豫。人既说豫，自然随之，则谦顺在君，说豫在人也。若以人君喜乐游豫，人则随之，纣作靡靡之乐，长夜之饮，何为天下离叛乎？故韩康伯云：“顺以动者，众之所随。”在於人君取致豫之义，然后为物所随，所以非斥先儒也。</p><p>故受之以《随》。以喜随人者，必有事，故受之以《蛊》。蛊者，事也。有事而后可大，可大之业，由事而生。故受之以《临》。临者，大也。物大然后可观，故受之以《观》。可观而后有所合，故受之以《噬嗑》。可观则异方合会也。嗑者，合也。物不可以苟合而巳，故受之以《贲》。贲者，饰也。物相合则须饰，以脩外也。致饰然后亨则尽矣，故受之以《剥》。极饰则实丧也。剥者，剥也。物不可以终尽剥，穷上反下，故受之以《复》。复则不妄矣，故受之以《无妄》。有无妄然后可畜，故受之以《大畜》。物畜然后可养，故受之以《颐》。颐者，养也。不养则不可动，故受之以《大过》。不养则不可动，养过则厚。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：郑玄云：“以养贤者宜过於厚。”王辅嗣注此卦云：“音相过之过。”韩氏云：“养过则厚。”与郑玄、辅嗣义同。唯王肃云：“过莫大於不养。”则以为过失之过。案此《序卦》以《大过》次《颐》也。明所过在养。子雍以为过在不养，违《经》反义，莫此之尤。而周氏等不悟其非，兼以过失释《大过》之名，巳具论之於《经》也。</p><p>物不可以终过，故受之以《坎》。坎者，陷也。过而不巳，则陷没也。陷必有所丽，故受之以《离》。离者，丽也。物穷则变，极陷则反所丽也。有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。言《咸》卦之义也。凡《序卦》所明，非《易》之缊也，盖囚卦之次，讬以明义。《咸》柔上而刚下，感应以相与。夫妇之象，莫美乎斯。人伦之道，莫大乎夫妇。故夫子殷勤深述其义，以崇人伦之始，而不系之於离也。先儒以《乾》至《离》为上《经》，天道也。《咸》至《未济》为下《经》，人事也。夫《易》六画成卦，三材必备，错综天人以效变化，岂有天道人事偏於上下哉？斯盖守文而不求义，失之远矣。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：韩於此一节注破先儒上《经》明天道，下《经》明人事，於《咸》卦之初巳论之矣。</p><p>夫妇之道不可以不久也，故受之以《恒》。恒者，久也。物不可以久居其所，故受之以《遯》。遯者，退也。夫妇之道，以恒为贵。而物之所居，不可以恒，宜与世升降，有时而遯也。物不可以终遯，遯，君子以远小人。遯而后亨，何可终邪？则小人遂陵，君子日消也。故受之以《大壮》。阳盛阴消，君子道胜。物不可以终壮，故受之以《晋》。《晋》以柔而进也。晋者，进也。虽以柔而进，要是进也。进必有所伤，故受之以《明夷》。日中则昃，月盈则食。夷者，伤也。伤於外者，必反於家，故受之以《家人》。伤於外，必反脩诸内。家道穷必乖，室家至亲，过在失节。故《家人》之义，唯严与敬。乐胜则流，礼胜则离。家人尚严其敝，必乖也。故受之以《睽》。睽者，乖也。乖必有难，故受之以《蹇》。蹇者，难也。物不可以终难，故受之以《解》，解者，缓也。缓必有所失，故受之以《损》。损而不巳必益，故受之以《益》。益而不巳必决，益而不巳，则盈，故必决也。故受之以《夬》。夬者，决也。决必有遇，以正决邪，必有喜遇也。故受之以《姤》，姤者，遇也。物相遇而后聚，故受之以《萃》。萃者，聚也。聚而上者谓之升，故受之以《升》。升而不巳必困，故受之以《困》。困乎上者必反下，故受之以《井》。井道不可不革，井久则浊秽，宜革易其故。故受之以《革》。革物者莫若鼎，故受之以《鼎》。革去故，鼎取新。既以去故，则宜制器立法以治新也。鼎所以和齐生物，成新之器也，故取象焉。主器者莫若长子，故受之以《震》。震者，动也。物不可以终动，止之，故受之以《艮艮者，止也。物不可以终止，故受之以《渐》。渐者，进也。进必有所归，故受之以《归妹》。得其所归者必大，故受之以《丰》。丰者，大也。穷大者必失其居，故受之以《旅》。旅而无所容，故受之以《巽》。旅而无所容，以巽则得出入也。巽者，入也。入而后说之，故受之以《兑》。兑者，说也。说而后散之，故受之以《涣》。说不可偏系，故宜散也。涣者，离也。涣者发畅而无所壅滞则殊趣，各肆而不反则遂乖离也。物不可以终离，故受之以《节》。夫事有其节，则物之所同守而不散越也。节而信之，故受之以《中孚》。孚，信也，既巳有节，则宜信以守之。有其信者必行之，故受之以《小过》。守其信者，则失贞而不谅之道，而以信为过，故曰小过也。有过物者必济，行过乎恭，礼过乎俭，可以矫世厉俗，有所济也。故受之以《既济》。物不可穷也，故受之以《未济》。终焉。有为而能济者，以巳穷物者也。物穷则乖，功极则乱，其可济乎？故受之以《未济》也。</p><p>最后更新时间:</p><p>本站内容均属公共领域且标明来源，仅限用于个人研究，未经允许，禁止转载。</p><p>工信部ICP备案号：京ICP备2024083108号-1</p>',89)])])}const m=a(t,[["render",h]]);export{_ as __pageData,m as default};
